static int[][] merge(int[][] iv) {
  Arrays.sort(iv, (a, b) -> Integer.compare(a[0], b[0]));
  List<int[]> out = new ArrayList<>();
  for (int[] x : iv) {
    if (out.isEmpty() || x[0] > out.get(out.size() - 1)[1]) out.add(new int[]{x[0], x[1]});
    else out.get(out.size() - 1)[1] = Math.max(out.get(out.size() - 1)[1], x[1]);
  }
  return out.toArray(new int[0][]);
}

import heapq

def min_rooms(meetings):
    meetings = sorted(meetings, key=lambda m: m[0])
    ends = []
    for s, e in meetings:
        if ends and ends[0] <= s:
            heapq.heappop(ends)
        heapq.heappush(ends, e)
    return len(ends)

static boolean inSubnet(int ip, int network, int prefixLen) {
  int mask = prefixLen == 0 ? 0 : -1 << (32 - prefixLen);
  return (ip & mask) == (network & mask);
}

def popcount(n):
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count

def missing_number(nums):
    x = len(nums)
    for i, v in enumerate(nums):
        x ^= i ^ v
    return x
